                    m.insert("numTokens".to_string(), Value::from(self.parse_to_int(amountInt.map(Value::from).unwrap_or(Value::Null))));
                    m.insert("nonce".to_string(), requestSignature.get("nonce").cloned().unwrap_or(Value::Null));
